insert into public.ref_survey_items (code, block, sub_construct, wording, is_reverse, in_baseline, in_pulse, pulse_rotates, in_half_yearly, in_annual, section, position) values
  ('CII-01', 'C4', 'clarity', 'Our team has a clear understanding of who the subject matter experts are for different aspects of our work.', false, true, false, false, true, true, 'A', 1),
  ('CII-02', 'C4', 'clarity', 'When I need specific expertise, I know exactly who on the team to go to.', false, true, false, false, true, true, 'A', 2),
  ('CII-06', 'C4', 'trust', 'I trust the work my team members produce without needing to second-guess it.', false, true, false, false, true, true, 'A', 3),
  ('CII-07', 'C4', 'trust', 'When a colleague gives me information or advice, I act on it with confidence.', false, true, false, false, true, true, 'A', 4),
  ('CII-11', 'C4', 'flow', 'Information moves across our team without bottlenecks.', false, true, false, false, true, true, 'A', 5),
  ('CII-12', 'C4', 'flow', 'Our team combines individual knowledge into collective output smoothly.', false, true, false, false, true, true, 'A', 6),
  ('TSI2-01', 'S2', null, 'Our team has enough uninterrupted time to focus on meaningful work.', false, true, true, false, true, true, 'A', 7),
  ('TSI2-02', 'S2', null, 'Handoffs between our team and other groups work smoothly.', false, true, true, false, true, true, 'A', 8),
  ('TSI3-01', 'S3', 'task', 'On our team, we challenge each other''s ideas openly when we disagree about how to do the work.', false, true, false, false, true, true, 'A', 9),
  ('TSI3-02', 'S3', 'task', 'When we have different opinions about how to approach a problem, we debate them productively.', false, true, false, false, true, true, 'A', 10),
  ('CII-03', 'C4', 'clarity', 'Team members openly acknowledge their areas of strength and the areas where others know more.', false, true, false, false, true, true, 'A', 11),
  ('CII-04', 'C4', 'clarity', 'We make good use of the different expertise across our team.', false, true, false, false, true, true, 'A', 12),
  ('CII-08', 'C4', 'trust', 'We openly trust each other''s professional judgement on complex issues.', false, true, false, false, true, true, 'A', 13),
  ('CII-09', 'C4', 'trust', 'Our team treats each other''s expertise as reliable and authoritative.', false, true, false, false, true, true, 'A', 14),
  ('CII-13', 'C4', 'flow', 'We adapt quickly to new challenges because we know how to draw on each other''s strengths.', false, true, true, true, true, true, 'A', 15),
  ('CII-14', 'C4', 'flow', 'Coordinating expertise across our team feels effortless rather than forced.', false, true, false, false, true, true, 'A', 16),
  ('TSI2-03', 'S2', null, 'I spend too much of my week in meetings that don''t really need me.', true, true, true, false, true, true, 'A', 17),
  ('TSI3-03', 'S3', 'task', 'Our team is comfortable having robust discussions about work decisions.', false, true, false, false, false, true, 'A', 18),
  ('TSI3-04', 'S3', 'relationship', 'There is real interpersonal friction or animosity on our team.', true, true, false, false, true, true, 'A', 19),
  ('TSI3-05', 'S3', 'relationship', 'Personality clashes affect how well our team gets work done.', true, true, false, false, false, true, 'A', 20),
  ('CII-05', 'C4', 'clarity', 'When a new problem arises, it is often unclear who has the relevant knowledge to address it.', true, true, false, false, true, true, 'A', 21),
  ('CII-10', 'C4', 'trust', 'I often feel I need to verify my colleagues'' work before relying on it.', true, true, false, false, true, true, 'A', 22),
  ('CII-15', 'C4', 'flow', 'It often takes too long to bring the right people and information together to solve a problem.', true, true, false, false, true, true, 'A', 23),
  ('OI1-01', 'O1', 'role_clarity', 'I am clear on what is expected of me in my role.', false, true, false, false, true, true, 'B', 24),
  ('OI1-02', 'O1', 'role_clarity', 'I know how my performance is evaluated and what success looks like in my role.', false, true, false, false, true, true, 'B', 25),
  ('OI1-04', 'O1', 'decision_rights', 'I have the authority I need to make decisions about my own work.', false, true, false, false, true, true, 'B', 26),
  ('OI1-05', 'O1', 'decision_rights', 'It''s clear in this team who has authority to make which decisions.', false, true, false, false, true, true, 'B', 27),
  ('OI1-07', 'O1', 'cascade', 'I understand how my work connects to the organisation''s strategic priorities.', false, true, false, false, true, true, 'B', 28),
  ('OI1-08', 'O1', 'cascade', 'The goals my team is working towards are clearly linked to the broader organisation''s goals.', false, true, false, false, false, true, 'B', 29),
  ('OI1-03', 'O1', 'role_clarity', 'I often receive conflicting instructions about what I should be doing.', true, true, false, false, false, true, 'B', 30),
  ('OI1-06', 'O1', 'decision_rights', 'Decisions that should be made quickly often get held up needing extra approvals.', true, true, false, false, false, true, 'B', 31),
  ('OI2-01', 'O2', null, 'I have the tools and systems I need to do my work effectively.', false, true, false, false, true, true, 'B', 32),
  ('OI2-02', 'O2', null, 'I can get the information and data I need to do my work without unreasonable delay.', false, true, false, false, true, true, 'B', 33),
  ('OI2-03', 'O2', null, 'The tools we use work well together rather than against each other.', false, true, false, false, true, true, 'B', 34),
  ('OI2-04', 'O2', null, 'I often have to use workarounds because our systems don''t do what I need them to.', true, true, false, false, true, true, 'B', 35),
  ('OI3-01', 'O3', null, 'The processes we use to get work done are clear and easy to follow.', false, true, false, false, true, true, 'B', 36),
  ('OI3-02', 'O3', null, 'Work moves through our team without getting stuck in unnecessary steps or approvals.', false, true, false, false, true, true, 'B', 37),
  ('OI3-03', 'O3', null, 'I spend an appropriate amount of my time on the work that actually matters, not on admin or rework.', false, true, false, false, true, true, 'B', 38),
  ('OI3-04', 'O3', null, 'When something goes wrong, we have a clear way to fix it without making the whole process slow.', false, true, false, false, true, true, 'B', 39),
  ('OI3-05', 'O3', null, 'A lot of the work I do feels like duplicate effort or rework.', true, true, false, false, true, true, 'B', 40),
  ('OI4-01', 'O4', null, 'I have enough time to do my work to the standard expected.', false, true, false, false, true, true, 'B', 41),
  ('OI4-02', 'O4', null, 'Our team has the resources (people, budget, capacity) it needs to deliver what''s being asked.', false, true, false, false, true, true, 'B', 42),
  ('OI4-03', 'O4', null, 'I regularly have to work outside normal hours just to keep up with my workload.', true, true, false, false, true, true, 'B', 43),
  ('OI5-01', 'O5', null, 'My manager helps me remove obstacles that are getting in the way of my work.', false, true, true, false, true, true, 'B', 44),
  ('OI5-02', 'O5', null, 'My manager backs my decisions and gives me appropriate latitude to act.', false, true, true, false, true, true, 'B', 45),
  ('OI5-03', 'O5', null, 'My manager actively makes our team''s work easier rather than harder.', false, true, true, false, true, true, 'B', 46),
  ('MI1-01', 'M1', 'engagement', 'I look forward to coming to work most days.', false, true, true, true, true, true, 'C', 47),
  ('MI1-02', 'M1', 'engagement', 'I am willing to put in extra effort when my team needs it.', false, true, true, true, true, true, 'C', 48),
  ('MI1-03', 'M1', 'engagement', 'When I''m working, time tends to fly by.', false, true, false, false, true, true, 'C', 49),
  ('MI1-05', 'M1', 'team_confidence', 'I am confident our team can deliver on the goals we''ve been set.', false, true, true, true, true, true, 'C', 50),
  ('MI1-06', 'M1', 'team_confidence', 'When our team faces tough problems, we find a way through them.', false, true, false, false, true, true, 'C', 51),
  ('MI1-07', 'M1', 'pride', 'I''d recommend this organisation as a good place to work.', false, true, true, true, true, true, 'C', 52),
  ('MI1-08', 'M1', 'pride', 'I feel proud to be part of this team and organisation.', false, true, false, false, true, true, 'C', 53),
  ('MI1-04', 'M1', 'engagement', 'I often feel drained or disengaged at work.', true, true, true, true, true, true, 'C', 54),
  ('MI2-01', 'M2', null, 'On our team, people can raise concerns or disagreements without fear of being penalised.', false, true, true, true, true, true, 'C', 55),
  ('MI2-02', 'M2', null, 'If I make a mistake at work, I feel safe disclosing it so we can fix it and learn.', false, true, true, true, true, true, 'C', 56),
  ('MI2-03', 'M2', null, 'Our team discusses difficult issues openly rather than avoiding them.', false, true, true, true, true, true, 'C', 57),
  ('MI2-04', 'M2', null, 'I can voice an opinion that goes against the group view without it damaging my standing.', false, true, false, false, true, true, 'C', 58),
  ('MI2-05', 'M2', null, 'People on this team often get punished or dismissed for raising problems.', true, true, false, false, true, true, 'C', 59),
  ('MI3-01', 'M3', null, 'I do my work because I find it genuinely interesting.', false, true, false, false, false, true, 'C', 60),
  ('MI3-02', 'M3', null, 'The work I do aligns with what I personally value as important.', false, true, false, false, false, true, 'C', 61),
  ('MI3-03', 'M3', null, 'I have meaningful choice in how I do my work.', false, true, false, false, false, true, 'C', 62),
  ('MI3-05', 'M3', null, 'When I do my work well, I feel a sense of personal accomplishment from it.', false, true, false, false, false, true, 'C', 63),
  ('MI3-04', 'M3', null, 'I do my work mainly because I have to, not because I want to.', true, true, false, false, false, true, 'C', 64),
  ('MI4-01', 'M4', null, 'My work has personal meaning for me.', false, true, false, false, false, true, 'C', 65),
  ('MI4-02', 'M4', null, 'The purpose of this organisation is something I can stand behind.', false, true, false, false, false, true, 'C', 66),
  ('MI4-03', 'M4', null, 'What I do at work matters in a broader sense, beyond the immediate task.', false, true, false, false, false, true, 'C', 67),
  ('MI4-04', 'M4', null, 'I struggle to see why what we do really matters.', true, true, false, false, false, true, 'C', 68),
  ('TW-01', 'TW', null, 'I am paid fairly for the work I do compared to others in similar roles.', false, true, true, true, true, true, 'C', 69),
  ('TW-02', 'TW', null, 'People in this team are treated fairly and respectfully regardless of their background.', false, true, true, true, true, true, 'C', 70),
