insert into public.ref_module_items (code, module_code, position, wording, response_kind, anchors, is_reverse, online, portal_code) values
  ('O1C-01', 'M-O1-CASCADE', 1, 'I can clearly describe how my work contributes to our team''s goals.', 'agree5', null, false, true, false),
  ('O1C-02', 'M-O1-CASCADE', 2, 'I can clearly describe how my team''s goals connect to the organisation''s broader priorities.', 'agree5', null, false, true, false),
  ('O1C-03', 'M-O1-CASCADE', 3, 'I know what our organisation is trying to achieve and why.', 'agree5', null, false, true, false),
  ('O1C-04', 'M-O1-CASCADE', 4, 'When priorities change at the organisation level, the implications for my work are explained clearly.', 'agree5', null, false, true, false),
  ('O1C-05', 'M-O1-CASCADE', 5, 'Sometimes I find myself doing work that doesn''t seem to connect to what the organisation is trying to achieve.', 'agree5', null, true, true, false),
  ('O2I-01', 'M-O2-IA', 1, 'When I need information to do my work, I can find it without significant delay.', 'agree5', null, false, true, false),
  ('O2I-02', 'M-O2-IA', 2, 'The information available to me is accurate and current.', 'agree5', null, false, true, false),
  ('O2I-03', 'M-O2-IA', 3, 'I often need to ask colleagues for information that should be available in our systems.', 'agree5', null, true, true, false),
  ('O2I-04', 'M-O2-IA', 4, 'I spend significant time each week working around limitations in our tools or systems.', 'agree5', null, true, true, false),
  ('O2I-05', 'M-O2-IA', 5, 'The systems I use to do my work integrate well with each other.', 'agree5', null, false, true, false),
  ('O2I-06', 'M-O2-IA', 6, 'I sometimes have to re-enter or copy information between systems that should connect automatically.', 'agree5', null, true, true, false),
  ('O2I-07', 'M-O2-IA', 7, 'What is the single most significant tool or information access issue in your work? (Optional, open-text)', 'open_text', null, false, false, false),
  ('O3P-01', 'M-O3-PF', 1, 'This process is clear and easy to follow.', 'agree5', null, false, true, false),
  ('O3P-02', 'M-O3-PF', 2, 'Work moves through this process without unnecessary delays or approvals.', 'agree5', null, false, true, false),
  ('O3P-03', 'M-O3-PF', 3, 'Information and inputs are typically ready when this process needs them.', 'agree5', null, false, true, false),
  ('O3P-04', 'M-O3-PF', 4, 'When something needs to be reworked or corrected in this process, the rework usually slows it down significantly.', 'agree5', null, true, true, false),
  ('O3P-05', 'M-O3-PF', 5, 'Handoffs in this process (between people, teams or systems) work smoothly.', 'agree5', null, false, true, false),
  ('O3P-06', 'M-O3-PF', 6, 'I spend appropriate time on the value-adding parts of this process, not on admin or workarounds.', 'agree5', null, false, true, false),
  ('O3P-07', 'M-O3-PF', 7, 'Where in this process is the biggest bottleneck or source of friction? (Optional, open-text)', 'open_text', null, false, false, false),
  ('O1L-01', 'M-O1-LT', 1, 'Who Recommends this decision?', 'rapid_multi', null, false, true, true),
  ('O1L-02', 'M-O1-LT', 2, 'Who Agrees must be consulted before this decision?', 'rapid_multi', null, false, true, true),
  ('O1L-03', 'M-O1-LT', 3, 'Who Performs (implements) this decision?', 'rapid_multi', null, false, true, true),
  ('O1L-04', 'M-O1-LT', 4, 'Who provides Input on this decision?', 'rapid_multi', null, false, true, true),
  ('O1L-05', 'M-O1-LT', 5, 'Who Decides (has decision authority) on this decision?', 'rapid_single', null, false, true, true),
  ('O1L-06', 'M-O1-LT', 6, 'How clear are the decision rights for this type of decision?', 'anchored5', '[{"value":1,"label":"Very unclear","description":null},{"value":5,"label":"Very clear","description":null}]'::jsonb, false, true, true),
  ('C1M-01', 'M-C1-MGR', 1, '[Skill name]: rate this person''s current demonstrated proficiency', 'anchored5', '[{"value":1,"label":"Novice","description":null},{"value":2,"label":"Developing","description":null},{"value":3,"label":"Proficient","description":null},{"value":4,"label":"Advanced","description":null},{"value":5,"label":"Expert","description":null}]'::jsonb, false, true, true),
  ('C2M-01', 'M-C2-MGR', 1, '[Domain name]: rate this person''s current working knowledge', 'anchored5', '[{"value":1,"label":"Little working knowledge","description":null},{"value":2,"label":"Basic; needs frequent reference or help","description":null},{"value":3,"label":"Sound working knowledge for the role","description":null},{"value":4,"label":"Deep knowledge; handles non-routine cases","description":null},{"value":5,"label":"An authority others consult","description":null}]'::jsonb, false, true, true),
  ('C3M-01', 'M-C3-MGR', 1, 'Performance band', 'band5', '[{"value":1,"label":"Underperforming","description":"Consistent gaps in delivery; performance management intervention warranted"},{"value":2,"label":"Developing / partial meet","description":"Meets some expectations; gaps in delivery quality or scope"},{"value":3,"label":"Meeting expectations","description":"Delivers reliably at the role''s expected standard"},{"value":4,"label":"Exceeding expectations","description":"Consistently delivers above the role''s expected standard"},{"value":5,"label":"Exceptional contributor","description":"Consistently exceeds expectations in scope and quality; recognised as a top performer"}]'::jsonb, false, true, true),
  ('C3M-02', 'M-C3-MGR', 2, 'Evidence basis', 'evidence_note', null, false, true, true),
  ('C5L-01', 'M-C5-TL', 1, 'How long does it typically take for a new team member to make their first meaningful contribution?', 'anchored5', '[{"value":1,"label":">12 weeks","description":null},{"value":2,"label":"8-12 weeks","description":null},{"value":3,"label":"4-8 weeks","description":null},{"value":4,"label":"2-4 weeks","description":null},{"value":5,"label":"<2 weeks","description":null}]'::jsonb, false, true, false),
  ('C5L-02', 'M-C5-TL', 2, 'How structured is your team''s onboarding for new members?', 'anchored5', '[{"value":1,"label":"No structure","description":null},{"value":5,"label":"Highly structured with clear milestones","description":null}]'::jsonb, false, true, false),
  ('C5L-03', 'M-C5-TL', 3, 'When a new tool or process is introduced, how long until your team is using it productively?', 'anchored5', '[{"value":1,"label":">90 days","description":null},{"value":5,"label":"<30 days","description":null}]'::jsonb, false, true, false),
  ('C5L-04', 'M-C5-TL', 4, 'How smoothly does your team adopt new tools or processes?', 'anchored5', '[{"value":1,"label":"Significant resistance/disruption","description":null},{"value":5,"label":"Smooth and rapid","description":null}]'::jsonb, false, true, false),
  ('C5L-05', 'M-C5-TL', 5, 'How often does your team formally review what worked and what didn''t on completed work?', 'anchored5', '[{"value":1,"label":"Never","description":null},{"value":2,"label":"Rarely","description":null},{"value":3,"label":"Sometimes","description":null},{"value":4,"label":"Regularly","description":null},{"value":5,"label":"After every significant piece of work","description":null}]'::jsonb, false, true, false),
  ('C5L-06', 'M-C5-TL', 6, 'When your team identifies a learning from a retrospective, how reliably does it get applied to subsequent work?', 'anchored5', '[{"value":1,"label":"Rarely","description":null},{"value":5,"label":"Almost always","description":null}]'::jsonb, false, true, false),
  ('C5L-07', 'M-C5-TL', 7, 'How regularly does your team share learning or new knowledge across team members?', 'anchored5', '[{"value":1,"label":"Rarely","description":null},{"value":5,"label":"As a regular practice","description":null}]'::jsonb, false, true, false),
  ('C5L-08', 'M-C5-TL', 8, 'When a team member learns something new and useful, how easily does the rest of the team gain access to that knowledge?', 'anchored5', '[{"value":1,"label":"Difficult","description":null},{"value":5,"label":"Effortless","description":null}]'::jsonb, false, true, false),
  ('C5L-09', 'M-C5-TL', 9, 'How safe is it for your team members to try new approaches that might not work?', 'anchored5', '[{"value":1,"label":"Not safe — failures are penalised","description":null},{"value":5,"label":"Very safe — experimentation is encouraged","description":null}]'::jsonb, false, true, false),
  ('C5L-10', 'M-C5-TL', 10, 'How does your team treat mistakes and failures?', 'anchored5', '[{"value":1,"label":"Punitive","description":null},{"value":5,"label":"As learning opportunities","description":null}]'::jsonb, false, true, false),
  ('C5L-11', 'M-C5-TL', 11, 'How readily does your team accept the temporary or permanent transfer of team members to or from other teams?', 'anchored5', '[{"value":1,"label":"Significant friction","description":null},{"value":5,"label":"Smooth and embraced","description":null}]'::jsonb, false, true, false),
  ('C5L-12', 'M-C5-TL', 12, 'How actively does your team consume external learning (industry conferences, courses, professional reading)?', 'anchored5', '[{"value":1,"label":"Minimally","description":null},{"value":5,"label":"Highly actively","description":null}]'::jsonb, false, true, false)
