insert into public.ref_admin_checklist_facts (code, checklist_code, position, wording, response_kind, source_response) values
  ('RA-1', 'ADM-O1', 1, 'A written position description exists and was reviewed or updated within the last 24 months.', 'yes_no', null),
  ('RA-2', 'ADM-O1', 2, 'The position description states success measures or accountabilities, not only duties.', 'yes_no', null),
  ('RA-3', 'ADM-O1', 3, 'The position description, or a delegations document it refers to, states the decisions the role can make without approval.', 'yes_no', null),
  ('TI-1', 'ADM-O2', 1, 'The system has a named owner accountable for it.', 'yes_no', 'Yes 1, No 0'),
